-- RetainIQ Data Loading Script
-- Run after: 01_tables.sql
-- Requires: CSV files generated by scripts/generate_data.py in data/ directory
USE DATABASE RETAINIQ_DB;
USE SCHEMA RAW;
USE WAREHOUSE RETAINIQ_WH;

-- 1. File format for CSV loading
CREATE OR REPLACE FILE FORMAT CSV_FORMAT
    TYPE = 'CSV'
    FIELD_OPTIONALLY_ENCLOSED_BY = '"'
    SKIP_HEADER = 1
    NULL_IF = ('NULL', '')
    FIELD_DELIMITER = ','
    TRIM_SPACE = TRUE;

-- 2. Internal stage
CREATE OR REPLACE STAGE DATA_STAGE FILE_FORMAT = CSV_FORMAT;

-- 3. Upload CSV files (run from CoCo or SnowSQL)
-- PUT 'file://path/to/data/customers.csv'    @DATA_STAGE/customers/    AUTO_COMPRESS=FALSE;
-- PUT 'file://path/to/data/policies.csv'     @DATA_STAGE/policies/     AUTO_COMPRESS=FALSE;
-- PUT 'file://path/to/data/claims.csv'       @DATA_STAGE/claims/       AUTO_COMPRESS=FALSE;
-- PUT 'file://path/to/data/payments.csv'     @DATA_STAGE/payments/     AUTO_COMPRESS=FALSE;
-- PUT 'file://path/to/data/interactions.csv' @DATA_STAGE/interactions/ AUTO_COMPRESS=FALSE;

-- 4. Load in FK order: CUSTOMERS -> POLICIES -> CLAIMS, PAYMENTS -> INTERACTIONS
COPY INTO CUSTOMERS (CUSTOMER_ID, FIRST_NAME, LAST_NAME, AGE, GENDER, CITY, STATE, PIN_CODE, PHONE, EMAIL, SEGMENT, PREFERRED_LANGUAGE)
FROM @DATA_STAGE/customers/ FILE_FORMAT = CSV_FORMAT;

COPY INTO POLICIES (POLICY_ID, CUSTOMER_ID, PRODUCT_TYPE, VEHICLE_TYPE, VEHICLE_MAKE, VEHICLE_MODEL, VEHICLE_YEAR, PLAN_NAME, SUM_INSURED, PREMIUM_AMOUNT, PAYMENT_FREQUENCY, START_DATE, END_DATE, RENEWAL_DATE, STATUS, NCB_PERCENTAGE, AUTO_RENEW)
FROM @DATA_STAGE/policies/ FILE_FORMAT = CSV_FORMAT;

COPY INTO CLAIMS (CLAIM_ID, POLICY_ID, CUSTOMER_ID, CLAIM_DATE, CLAIM_AMOUNT, APPROVED_AMOUNT, STATUS, CATEGORY, RESOLUTION_DATE, REJECTION_REASON, NOTES)
FROM @DATA_STAGE/claims/ FILE_FORMAT = CSV_FORMAT;

COPY INTO PAYMENTS (PAYMENT_ID, POLICY_ID, CUSTOMER_ID, DUE_DATE, PAID_DATE, AMOUNT, STATUS, PAYMENT_METHOD, LATE_FEE)
FROM @DATA_STAGE/payments/ FILE_FORMAT = CSV_FORMAT;

COPY INTO INTERACTIONS (INTERACTION_ID, CUSTOMER_ID, CHANNEL, DIRECTION, INTERACTION_TS, SUBJECT, CONTENT, SUMMARY, SENTIMENT_SCORE)
FROM @DATA_STAGE/interactions/ FILE_FORMAT = CSV_FORMAT;
